"""All full-matrix finite positional versus temporal validation operator results."""
import json,csv
import numpy as np
from .positional_operator_common import OUT,sha,guard

def summarize(p,r):
    rows=r['rows'];summaries=[];pairs=[]
    for rounds in p['positional_samples']:
        ratios=[];theory=[]
        for stage in range(24):
            rr=[]
            for seed in p['seeds']:
                single=next(z for z in rows if z['signature']=={**z['signature'],'stage':stage,'K':1,'T':4*rounds,'seed':seed});multi=next(z for z in rows if z['signature']=={**z['signature'],'stage':stage,'K':4,'T':rounds,'seed':seed});ratio=multi['observed_target_MSE']/single['observed_target_MSE'];rr.append(ratio);pairs.append({'stage':stage,'seed':seed,'updates_per_weight':4*rounds,'single_T':4*rounds,'positional_T':rounds,'positional_over_single_MSE':ratio,'single_MSE':single['observed_target_MSE'],'positional_MSE':multi['observed_target_MSE'],'predicted_ratio':multi['predicted_target_MSE']/single['predicted_target_MSE']})
            ratios.append(rr);theory.append(multi['predicted_target_MSE']/single['predicted_target_MSE'])
        ratio=np.array(ratios);seedlog=np.log(ratio).mean(0);mu=seedlog.mean();se=seedlog.std(ddof=1)/np.sqrt(len(seedlog));summaries.append({'updates_per_weight':4*rounds,'single_T':4*rounds,'positional_T':rounds,'geometric_MSE_ratio':float(np.exp(mu)),'approx_seed_sensitivity_lower':float(np.exp(mu-1.96*se)),'approx_seed_sensitivity_upper':float(np.exp(mu+1.96*se)),'predicted_geometric_ratio':float(np.exp(np.log(theory).mean())),'layers_positional_mean_MSE_lower':sum(np.mean([v['positional_MSE'] for v in pairs if v['stage']==stage and v['updates_per_weight']==4*rounds])<np.mean([v['single_MSE'] for v in pairs if v['stage']==stage and v['updates_per_weight']==4*rounds]) for stage in range(24))})
    return summaries,pairs

def main():
    p=json.loads((OUT/'protocol.json').read_text());guard(p);r=json.loads((OUT/'statistics.json').read_text());audit=json.loads((OUT/'evidence_audit.json').read_text());ca=json.loads((OUT/'control_audit.json').read_text());assert audit['passed'] and ca['passed'] and audit['producer_manifest_sha256']==sha(OUT/'manifest.json');summary,pairs=summarize(p,r)
    for name,rows in [('paired_operator_ratios.csv',pairs),('summary.csv',summary)]:
        with (OUT/name).open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
    lines=['# Finite positional versus temporal neural operators','','All24 affine Transformer matrices, five sampling seeds, four matched-update conditions and64 actual FP32-teacher activation rows per matrix. The same group16 F32 minmax lower/span and biases are used for both designs. One p-bit per normalized weight uses8-bit finite fields[-4,4]; the four-node positional word uses4-bit scalar quantization and two finite field levels +/-4. All endpoints are free. Every time step performs a sampled matrix operation and accumulates output before nonlinearities. This is reused validation data, not new held-out or full stochastic-network quality. The positional baseline is an internal construction, not a claim about Extropic\'s architecture.','','## Independently audited scope','',f'All960 original outputs replay byte-exact through separately built public THRML factors and sum-only observers. Separate integer-frequency replay satisfies every derived IEEE forward error envelope. Original-model hooks and checkpoint reconstruction verify all24 input matrices/targets and42,467,328 source weights, both controller formats, ranges and biases. Production node updates: {r["native_node_updates"]:,}; independent direct-sum plus count replay: {audit["independent_native_replay_updates"]:,}. This establishes simulated operators, not measured energy/latency/device area.','','## Equal node-update count','', '| Updates/weight | Single T | Positional T | Geometric positional/single target MSE | Approx. five-seed sensitivity | Predicted ratio | Layers with lower positional mean MSE |','|---:|---:|---:|---:|---:|---:|---:|']
    for row in summary:lines.append(f'| {row["updates_per_weight"]} | {row["single_T"]} | {row["positional_T"]} | {row["geometric_MSE_ratio"]:.6f} | [{row["approx_seed_sensitivity_lower"]:.6f}, {row["approx_seed_sensitivity_upper"]:.6f}] | {row["predicted_geometric_ratio"]:.6f} | {row["layers_positional_mean_MSE_lower"]}/24 |')
    lines+=['','The geometric ratio gives each layer equal weight; all480 raw paired ratios and every960 per-case MSE are retained. Seed intervals use normal1.96 times the five-seed standard error of layer-averaged log ratios, descriptive sensitivity only. They exclude checkpoint/text/device uncertainty and provide no held-out or physical guarantee. The analytic target error includes both fixed programmed-mean bias and conditional sampling variance. No practical20% gate or new quality threshold was invented after observing results.','','## Resources and remaining experiment','','Both designs use identical4 metadata bits per weight for group16 lower/span. Adding deterministic affine biases contributes.03125bits/weight. SPW has8 controller-code bits/weight, total12.03125; positional has4 programmed binary selectors/weight, total8.03125. A2-byte group-size flag per matrix adds48bytes globally. Shared control-level/field-map descriptors, dynamic stochastic states (one versus four per weight), physical control circuits, accumulator/readout/storage, calibration and simulator Python/JAX overhead are distinct. Code bits are logical serialized descriptions, not physical area or total memory. Runtime uses external F32 arithmetic.','','At equal updates, single uses one-quarter the dynamic p-bits but four times the parallel sample rounds, assuming concurrent transitions. Node-update counts cannot establish physical energy/latency. The same sampled matrix is shared across64 activation rows in a probe; this is not autoregressive generation latency. A full stochastic student-network comparison with matched task quality, followed by physical/controller accounting, remains required. Earlier failed numerical/quality gates stay unchanged. No new candidate was selected using held-out text. The broad research goal stays active.','','Reproduction: run `research.thrml_spw.verify_positional_operator_controls` in the model environment; run `research.thrml_spw.verify_positional_operators` in the recorded CUDA THRML environment with `XLA_FLAGS=--xla_gpu_autotune_level=0`; generate this report with `research.thrml_spw.positional_operator_report` in the CPU THRML environment. Source/protocol seals and exact raw outputs are retained.']
    report=OUT.parent/'POSITIONAL_OPERATOR_REPORT.md';report.write_text('\n'.join(lines)+'\n')
    import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
    fig,ax=plt.subplots(figsize=(7,4),layout='constrained');xx=[v['updates_per_weight'] for v in summary];yy=np.array([v['geometric_MSE_ratio'] for v in summary]);lo=np.array([v['approx_seed_sensitivity_lower'] for v in summary]);hi=np.array([v['approx_seed_sensitivity_upper'] for v in summary]);ax.errorbar(xx,yy,yerr=[yy-lo,hi-yy],fmt='o-',label='Actual native outputs');ax.plot(xx,[v['predicted_geometric_ratio'] for v in summary],'x--',label='Conditional variance + mean bias');ax.axhline(1,color='k',linestyle=':');ax.set(xscale='log',yscale='log',xlabel='Equal stochastic node updates per converted weight',ylabel='Geometric positional/single target MSE',title='All24 neural operators; consumed validation activations');ax.legend();fig.savefig(OUT.parent/'positional_operator_comparison.png',dpi=180);plt.close(fig);print(report)
if __name__=='__main__':main()
